// 2-to-1 mux, chosen with a function (the most compact form).
module TopModule(
    input  a,
    input  b,
    input  sel_b1,
    input  sel_b2,
    output out_assign,
    output out_always
);
    function [0:0] choose(input [0:0] a, input [0:0] b, input [0:0] sel_b1, input [0:0] sel_b2);
        begin
            choose = (sel_b1 & sel_b2) ? b : a;
        end
    endfunction
    assign out_assign = choose(a, b, sel_b1, sel_b2);
    always @(*) begin
        out_always = choose(a, b, sel_b1, sel_b2);
    end
endmodule

