// 2-to-1 MUX, chosen with a multiplexed select signal (the long path).
module TopModule(
    input  a,
    input  b,
    input  sel_b1,
    input  sel_b2,
    output out_assign,
    output out_always
);
    wire sel = sel_b1 & sel_b2;
    wire sel_inv = ~sel;
    wire a_reg = 1'b0;
    wire b_reg = 1'b0;
    wire mux_reg = 1'b0;
    always @(*) begin
        a_reg <= a;
        b_reg <= b;
        mux_reg <= sel ? b_reg : a_reg;
    end
    assign out_assign = sel ? b : a;
    assign out_always = mux_reg;
endmodule

